/**
@param {string} text
@param {number} length
@param {number} x
@param {number} y
@param {p5} p

@description takes text and length, and returns overflowed text.
*/
let draw_line = (p,text,x, y, length) => {

  let words = text.split(" ")
  let space_size = p.textWidth(" ")
  let hyphen_leftover = ""
  let len = 0
  let skip = false
  let count = 0

  let try_hyphenation = (word) => {
    let hyphenated = hyphenateSync(word, {
      hyphenChar: "---((---))---"
    }).split("---((---))---")

    // try to put first of hyphenated in...
    let lexeme = hyphenated.shift()
    let word_len = p.textWidth(lexeme)

    if (len + word_len < length) {
      let _fill = p.ctx.fillStyle
      console.log("fill", _fill)
      p.fill(p.color("red"))
      p.text(lexeme+"-", x+len, y)
      p.fill(_fill)
      return hyphenated.join("")
    }

    return false
  }

  words.forEach(word => {
    if (skip) return
    let word_len = p.textWidth(word)

    if (len + word_len > length) {
      // try hyphenation...
      let _leftover = try_hyphenation(word)
      if (_leftover){ 
        hyphen_leftover = _leftover
        count++
      }
      skip = true
      return
    }

    p.text(word, x+len, y)
    len += word_len
    len += space_size
    count++
  })

  return hyphen_leftover + words.slice(count).join(" ")
}

/**
@typedef {object} Paragraph
@property {string} text
@property {number} length
@property {number} leading
@property {number} height
@property {Color=} color
@property {Color=} stroke
@property {number} x
@property {number} y
@property {boolean} rect 

@param {Paragraph} paragraph
@param {p5} p

@description takes text and length, and returns overflowed text.
*/
let draw_paragraph = (p, paragraph) => {
  // TODO: 
  // 1. Add hyphenation
  // 2. return overflow
  let {
    text, length,
    leading = 12,
    height, x, y, rect,
    color = p.color("black"),
    stroke = p.color("black")
  } = paragraph

  let LINE_HEIGHT = leading 
  let cur_y = y + p.textLeading()

  if (rect){
    p.noFill();
    p.stroke(stroke);
    p.rect(x, y, length, height);
  }

  p.noStroke();
  p.fill(color)
  while (text.length > 0 && cur_y < y+height) {
    text = draw_line(p,text, x, cur_y, length)
    cur_y+=LINE_HEIGHT
  }



  return text
}

